#version 450
layout(location = 0) in vec2 uv;
layout(location = 0) out vec4 color;
layout(set = 0, binding = 0) uniform sampler2D source;

void main() {
    vec2 texel = 1.0 / vec2(textureSize(source, 0));
    vec4 sum = vec4(0.0);
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            sum += texture(source, uv + vec2(x, y) * texel);
        }
    }
    color = sum / 9.0;
}
